INSERT INTO public.products (id, name, slug, category, price, description, material, fit_note, care, images)
VALUES
('p1111111-1111-4111-8111-111111111111', 'Falling Flames Heavyweight Boxy Tee', 'falling-flames-heavyweight-boxy-tee', 'Tops', 75, 'Constructed from 290 GSM dry-touch organic combed cotton with stone-wash patina. Features a relaxed drop-shoulder cut, reinforced twin-needle 32mm ribbed collar band, and clean side split hems for an architectural drape.', '100% GOTS-certified Organic Combed Cotton (290 GSM)', 'Oversized, relaxed drop-shoulder silhouette. True to size for boxy aesthetic.', 'Machine wash cold inside-out at 30°C. Line dry in shade. Do not tumble dry.', ARRAY['https://images.unsplash.com/photo-1521572267360-ee0c2909d518?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1503342217505-b0a15ec3261c?auto=format&fit=crop&w=800&q=80']),
('p2222222-2222-4222-8222-222222222222', 'Pleated Relaxed Studio Trouser', 'pleated-relaxed-studio-trouser', 'Bottoms', 155, 'Tailored single-pleat trousers cut from Japanese tropical wool blend. Features a comfortable high-rise waist with hidden side adjusters, gentle taper toward the ankle, and interior French seams.', '60% Virgin Tropical Wool, 38% Recycled Poly, 2% Elastane', 'High-rise waist with relaxed thigh tapering to 18cm leg opening.', 'Dry clean only or delicate hand wash cold. Cool iron with pressing cloth.', ARRAY['https://images.unsplash.com/photo-1624378439575-d8705ad7ae80?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1509551388413-e18d0ac5d495?auto=format&fit=crop&w=800&q=80']),
('p3333333-3333-4333-8333-333333333333', 'Purgatory Brutalist Gabardine Trench', 'purgatory-brutalist-gabardine-trench', 'Outerwear', 310, 'An unlined minimalist outerwear statement engineered from water-resistant bonded cotton gabardine. Minimalist concealed horn button placket, deep raglan sleeves, storm welt pockets, and rear inverted pleat.', '100% Weather-Treated Bonded Cotton Gabardine', 'Generous mid-calf length. Sized to layer comfortably over heavyweight hoodies.', 'Specialist clean only. Wipe clean with damp sponge for minor spots.', ARRAY['https://images.unsplash.com/photo-1544923246-77307dd654cb?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1576995853123-5a10305d93c0?auto=format&fit=crop&w=800&q=80']),
('p4444444-4444-4444-8444-444444444444', 'Vibram Commando Lug Minimalist Derby', 'vibram-commando-lug-minimalist-derby', 'Footwear', 225, 'Constructed on an Italian last using full-grain matte calfskin leather paired with an ultra-lightweight Vibram Morflex lug sole. Goodyear welted construction allows for multi-year resoling.', 'Full-Grain Italian Calfskin Leather, Vibram Morflex Rubber Outsole', 'Fits true to EU/US standard. Half sizes recommended to size down.', 'Condition with neutral beeswax leather balm. Store with cedar shoe trees.', ARRAY['https://images.unsplash.com/photo-1533867617858-e7b97e060509?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=800&q=80']),
('p5555555-5555-4555-8555-555555555555', 'Seamless Heavy Gauge Merino Mockneck', 'seamless-heavy-gauge-merino-mockneck', 'Tops', 125, 'Knit on Japanese whole-garment 3D knitting machines from 19.5 micron ultra-fine Australian merino wool. 100% seam-free torso provides fluid movement with zero friction points.', '100% Extra-Fine Australian Merino Wool (19.5 Micron)', 'Tailored fit that skims the torso. Size up for a looser drape.', 'Hand wash in cool water with wool detergent. Dry flat on a clean towel.', ARRAY['https://images.unsplash.com/photo-1576566588028-4147f3842f27?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1618354691373-d851c5c3a990?auto=format&fit=crop&w=800&q=80']),
('p6666666-6666-4666-8666-666666666666', 'Architectural Cargo Pant', 'architectural-cargo-pant', 'Bottoms', 170, 'An austere reinterpretation of tactical utility. Low-profile bellows cargo pockets engineered flush to the leg seams. Cut from high-density organic ripstop cotton with articulated knee darts.', '100% High-Density Cotton Ripstop (240 GSM)', 'Mid-rise, articulated knee taper. Elasticated toggle hem cinch.', 'Machine wash cold with similar darks. Hang dry. Warm iron if necessary.', ARRAY['https://images.unsplash.com/photo-1517445312882-bc9910d016b7?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1541099649105-f69ad21f3246?auto=format&fit=crop&w=800&q=80']),
('p7777777-7777-4777-8777-777777777777', 'Falling Flames Technical Overshirt', 'falling-flames-technical-overshirt', 'Outerwear', 210, 'Multi-season layering piece crafted from lightweight Taslan nylon with matte peach-skin finish. Matte snaps, twin hidden chest pockets, and laser-cut underarm eyelets for thermoregulation.', '100% Water-repellent Peach-Skin Taslan Nylon', 'Square, boxy overshirt cut designed to fit over a t-shirt or knit.', 'Machine wash cold gentle. Do not bleach. Air dry only.', ARRAY['https://images.unsplash.com/photo-1548883354-7622d03aca27?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1551488831-00ddcb6c6bd3?auto=format&fit=crop&w=800&q=80']),
('p8888888-8888-4888-8888-888888888888', 'Molded Bio-EVA Minimalist Mule', 'molded-bio-eva-minimalist-mule', 'Footwear', 90, 'Single-pour bio-based sugarcane EVA foam slip-on mule. Sculpted anatomical footbed, zero-drop heel posture, and non-marking hexagonal traction channels.', '100% Bio-EVA SugarFoam™', 'Roomy relaxed forefoot. Designed to be worn with or without socks.', 'Rinse clean with water and neutral soap. Air dry away from direct heat.', ARRAY['https://images.unsplash.com/photo-1608256246200-53e635b5b65f?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560769629-975ec94e6a86?auto=format&fit=crop&w=800&q=80'])
